import{_ as a,c as o,o as t,b0 as s}from"./chunks/framework.BWMBvyU7.js";const r="/programming-docs/assets/image-20220604164114921.eWzp2xub.png",p=JSON.parse('{"title":"LV005-共享内存简介","description":null,"frontmatter":{"title":"LV005-共享内存简介","date":"2026-03-16T21:39:32.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/os/process-communication/shared-memory/126d38f372ac242369bf753d","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T21:39:32.578Z","fulluuid":"369bf753d20b48e2bcb483d58775643a","useduuid":"369bf753d"}},"headers":[],"relativePath":"sdoc/os/process-communication/shared-memory/126d38f372ac242369bf753d.md","filePath":"sdoc/03-操作系统/09-进程通信/15-共享内存/LV005-共享内存简介.md","lastUpdated":1773672539000}'),n={name:"sdoc/os/process-communication/shared-memory/126d38f372ac242369bf753d.md"};function d(c,e,l,i,m,_){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="lv005-共享内存简介" tabindex="-1">LV005-共享内存简介 <a class="header-anchor" href="#lv005-共享内存简介" aria-label="Permalink to &quot;LV005-共享内存简介&quot;">​</a></h1><h2 id="一、共享内存简介" tabindex="-1">一、共享内存简介 <a class="header-anchor" href="#一、共享内存简介" aria-label="Permalink to &quot;一、共享内存简介&quot;">​</a></h2><p>共享内存就是映射一段能被其它进程所访问的内存，这段共享内存由一个进程创建，但其它的多个进程都可以访问，使得多个进程可以访问同一块内存空间。共享内存是最快的<code>IPC</code>方式，它是针对其它进程间通信方式运行效率低而专门设计的，它往往与其它通信机制，例如结合信号量来使用，以实现进程间的同步和通信。</p><p><strong>共享内存的机制，就是拿出一块虚拟地址空间来，映射到相同的物理内存中</strong>。这样这一个进程写入的东西，另外一个进程马上就能看到了，都不需要拷贝来拷贝去，传来传去，大大提高了进程间通信的速度。</p><img src="'+r+'" alt="image-20220604164114921" style="zoom:43%;">',5)])])}const f=a(n,[["render",d]]);export{p as __pageData,f as default};
